'use client';

/**
 * <RoxyTarotCatalog data={...} />: Responsive tarot deck gallery with card art, name, and an arcana and suit caption from the tarot catalog response.
 *
 * You own this file. Customize freely. The component is re-exported from
 * @roxyapi/ui-react and stays in sync with the published package.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/tarot-catalog/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   const { data } = await roxy.someDomain.someMethod({ body: await req.json() });
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyTarotCatalog as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyTarotCatalogProps = ComponentProps<typeof Element>;

export function RoxyTarotCatalog(props: RoxyTarotCatalogProps) {
	return <Element {...props} />;
}

export default RoxyTarotCatalog;
